impl DeclarationResolutionStorage for ExposedDataPipeline {
    async fn read_resolution_input(&self) -> Result<ResolutionInput, EntityIngestionError> {
        let destination = self.resolved_declarations_path();
        if fs::try_exists(&destination).await.map_err(read_error)? {
            return Err(write_error("resolved declarations already exist").into());
        }
        let directory = self.cleaned_declarations_path();
        let (observations, observation_digest) =
            read_table::<Observation>(&directory.join("funders.parquet"), &funders_schema())?;
        let (payments, payment_digest) = read_table::<Payment>(
            &directory.join("funding_entries.parquet"),
            &funding_schema(),
        )?;
        ResolutionInput::new(
            observations,
            payments,
            BTreeMap::from([
                ("funders.parquet".into(), observation_digest),
                ("funding_entries.parquet".into(), payment_digest),
            ]),
        )
    }
    fn resolution_run_key(&self) -> String {
        crate::domain::models::entity_ingestion::IngestionKey::from(self.key()).to_string()
    }
    async fn publish_resolution(
        &self,
        result: &ResolvedDeclarations,
    ) -> Result<(), EntitySearchPipelineError> {
        let destination = self.resolved_declarations_path();
        let parent = destination
            .parent()
            .expect("resolved declarations have a parent");
        fs::create_dir_all(parent).await.map_err(write_error)?;
        let staging = parent.join(format!(".declarations-{}", Uuid::now_v7()));
        let publication = async {
            if fs::try_exists(&destination).await.map_err(write_error)? {
                return Err(write_error("resolved declarations already exist"));
            }
            fs::create_dir(&staging).await.map_err(write_error)?;
            write_table(
                &staging.join("observation_resolution.parquet"),
                observation_schema(),
                &result.observations,
            )
            .await?;
            write_table(
                &staging.join("payment_attribution.parquet"),
                attribution_schema(),
                &result.attributions,
            )
            .await?;
            write_table(
                &staging.join("pair_decisions.parquet"),
                pair_schema(),
                &result.pairs,
            )
            .await?;
            fs::write(
                staging.join("manifest.json"),
                serde_json::to_vec_pretty(&result.manifest).map_err(write_error)?,
            )
            .await
            .map_err(write_error)?;
            publish_directory(&staging, &destination).map_err(write_error)
        }
        .await;
        if publication.is_err() {
            let _ = fs::remove_dir_all(&staging).await;
        }
        publication
    }
}

pub(super) fn read_table<T: DeserializeOwned>(
    path: &Path,
    expected: &Schema,
) -> Result<(Vec<T>, String), EntitySearchPipelineError> {
    let bytes = std::fs::read(path).map_err(read_error)?;
    let digest = format!("{:x}", Sha256::digest(&bytes));
    let reader =
        ParquetRecordBatchReaderBuilder::try_new(bytes::Bytes::from(bytes)).map_err(read_error)?;
    if reader.schema().field_with_name("member_id").is_ok() {
        return Err(read_error(
            "unsupported member identity format; capture a new ingestion run, then clean, resolve and load it",
        ));
    }
    for required in expected.fields() {
        let actual=reader.schema().field_with_name(required.name()).map_err(|_|read_error("unsupported declaration artifact format; capture a new ingestion run, then clean, resolve and load it"))?;
        if actual.data_type() != required.data_type()
            || actual.is_nullable() != required.is_nullable()
        {
            return Err(read_error(format!(
                "cleaned field {} has an incompatible type; capture a new ingestion run, then clean, resolve and load it",
                required.name()
            )));
        }
    }
    let mut rows = Vec::new();
    for batch in reader.build().map_err(read_error)? {
        let mut writer = ArrayWriter::new(Vec::new());
        writer
            .write(&batch.map_err(read_error)?)
            .map_err(read_error)?;
    identities: &BTreeMap<String, Option<String>>,
    observations: &BTreeMap<String, FunderRow>,
    selected_identity_ids: &BTreeSet<String>,
) -> Vec<LoadFunder> {
    let mut funder_groups = BTreeMap::<String, Vec<&FunderRow>>::new();
    for (observation_id, identity_id) in identities {
        let Some(identity_id) = identity_id.as_ref() else {
            continue;
        };
        if selected_identity_ids.contains(identity_id) {
            funder_groups
                .entry(identity_id.clone())
                .or_default()
                .push(&observations[observation_id]);
        }
    }
    let mut load_funders = Vec::with_capacity(funder_groups.len());
    for (identity_id, mut group) in funder_groups {
        group.sort_by(|left, right| left.funder_id.cmp(&right.funder_id));
        let company_number = group
            .iter()
            .filter(|row| row.donor_kind.as_deref() == Some("Company"))
            .find_map(|row| row.donor_company_number.clone());
        let kind = if company_number.is_some() {
            Some("Company".to_owned())
        } else {
            group.iter().find_map(|row| row.donor_kind.clone())
        };
        let names = group
            .iter()
            .filter_map(|row| row.name_raw.as_deref())
            .filter(|name| !name.trim().is_empty());
        let aliases = group
            .iter()
            .filter_map(|row| row.name_raw.as_ref())
            .filter(|name| !name.trim().is_empty())
            .cloned()
            .collect::<BTreeSet<_>>();
        let name = canonical_name(names).map_or_else(
            || {
                company_number.as_ref().map_or_else(
                    || "Unnamed resolved funder".to_owned(),
                    |number| format!("Companies House {number}"),
                )
            },
            str::to_owned,
        );
        let aliases = aliases.into_iter().collect();
        load_funders.push(LoadFunder {
            identity_id,
            name,
            aliases,
            kind,
            company_number,
        });
    }
    load_funders
}

